//! syntax.c's syntax queries and scanning engine against pinned GNU:
//! char-syntax, matching-paren, syntax-class-to-char, scan-lists,
//! scan-sexps, forward-comment, backward-prefix-chars and
//! parse-partial-sexp over comment styles, nesting, fences, strings,
//! escapes, prefixes, narrowing, syntax-table properties, just-in-time
//! propertization, multibyte and unibyte text, and their signals.
use romacs_vm::Vm;

/// Shared by every case, in both implementations. `syn` builds and selects
/// a table as `make-syntax-table' does (GNU subr.el, absent from a bare
/// VM); `walk` collects successive `scan-sexps' results by COUNT from the
/// buffer's end, stopping at nil or a signal; `comments` and `stops` walk
/// `forward-comment' and `parse-partial-sexp' stops; `splits` checks that
/// continuing from every intermediate OLDSTATE reaches the whole parse.
/// `syntax-ppss' (syntax.el, absent from a bare VM) is its uncached
/// meaning, so back_comment's defun-start lookup runs the same Lisp in both.
const PRELUDE: &str = r#"(progn
 (setq comment-use-syntax-ppss REGIME)
 (defalias 'syntax-ppss (lambda (&optional pos) (save-excursion (parse-partial-sexp (point-min) (or pos (point))))))
 (defalias 'syn (lambda (&rest specs) (let ((st (make-char-table 'syntax-table))) (set-char-table-parent st (standard-syntax-table)) (while specs (modify-syntax-entry (car specs) (car (cdr specs)) st) (setq specs (cdr (cdr specs)))) (set-syntax-table st) st)))
 (defalias 'walk (lambda (n) (let ((p (if (> n 0) (point-min) (point-max))) (r nil)) (while (and p (< (length r) 60)) (setq p (condition-case e (scan-sexps p n) (error (list e)))) (setq r (cons p r)) (if (consp p) (setq p nil))) (nreverse r))))
 (defalias 'comments (lambda (n) (let ((p (if (> n 0) (point-min) (point-max))) (r nil) (go t)) (goto-char p) (while (and go (< (length r) 60)) (setq go (forward-comment n)) (setq r (cons (point) r)) (if (not go) (progn (setq go (if (> n 0) (< (point) (point-max)) (> (point) (point-min)))) (if go (forward-char (if (> n 0) 1 -1))) (setq r (cons (point) r))))) (nreverse r))))
 (defalias 'splits (lambda (&rest args) (let ((whole (apply #'parse-partial-sexp (point-min) (point-max) args)) (i (point-min)) (r nil)) (while (<= i (point-max)) (let* ((s1 (parse-partial-sexp (point-min) i)) (s2 (apply #'parse-partial-sexp i (point-max) (car args) (car (cdr args)) s1 (cdr (cdr args))))) (setq r (cons (if (equal s2 whole) t (list i s1 s2)) r))) (setq i (1+ i))) (list whole (delq t (nreverse r))))))
 (defalias 'stops (lambda (stop) (let ((s nil) (r nil) (n 0)) (goto-char (point-min)) (while (and (< (point) (point-max)) (< n 40)) (setq s (parse-partial-sexp (point) (point-max) nil nil s stop)) (setq r (cons (list (point) (nth 3 s) (nth 4 s) (nth 7 s) (nth 8 s)) r)) (setq n (1+ n))) (nreverse r))))
 EXPR)"#;

