#[test]
fn syntax_scanning_matches_pinned_gnu() {
    let binary = std::env::var("ROMACS_GNU_ORACLE").expect("pinned GNU oracle");
    let mut failures = Vec::new();
    let cases: Vec<&str> = CASES.lines().filter(|line| !line.is_empty()).collect();
    // find_defun_start through `syntax-ppss', and by open parens in column 0.
    for (regime, expression) in ["t", "nil"].into_iter().flat_map(|r| cases.iter().map(move |e| (r, e))) {
        // As character codes, as tests/json.rs compares.
        let body = format!("(append (prin1-to-string (condition-case e {expression} (error (list 'signal e)))) nil)");
        let source = PRELUDE.replace("EXPR", &body).replace("REGIME", regime);
        let output = std::process::Command::new(&binary).args(["-Q", "--batch", "--eval", &format!("(prin1 {source})")]).output().unwrap();
        assert!(output.status.success(), "{expression}\n{}", String::from_utf8_lossy(&output.stderr));
        let expected = String::from_utf8(output.stdout).unwrap();
        let mut vm = Vm::new();
        vm.install_lisp_prelude().unwrap();
        let actual = vm.eval_source(&source).and_then(|v| v.display());
        if actual.as_deref() != Ok(expected.as_str()) {
            let text = |codes: &str| codes.trim_matches(|c| c == '(' || c == ')').split_whitespace()
                .filter_map(|n| n.parse::<u32>().ok().and_then(char::from_u32)).collect::<String>();
            failures.push(format!("[comment-use-syntax-ppss {regime}] {expression}\n  GNU    {}\n  Romacs {:?}", text(&expected), actual.as_deref().map(text)));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n{}", failures.len(), 2 * cases.len(), failures.join("\n"));
}
